import{apiClient}from"./client";const getCars=async a=>{return(await apiClient.get("/carList?organizationSlug=kr-bogdanauto.hyundai",{params:a?{organizationSlug:a}:{}})).data.items},getCarByVin=async(a,t)=>{return(await apiClient.get(`/carList/${a}?organizationSlug=kr-bogdanauto.hyundai`,{params:{organizationSlug:t}})).data};export{getCars,getCarByVin};